import base64
import io
import requests

import bot
import v53_attractive_customer_experience_bootstrap as v53

# V54 - themed public banner + persistent Telegram Open App menu.
# Existing admin/referral/checker/business logic is inherited unchanged.

_BANNER_B64 = ""

_original_start = bot.start

async def v54_start(update, context):
    try:
        banner = io.BytesIO(base64.b64decode(_BANNER_B64))
        banner.name = "betroxy_theme.jpg"
        await update.effective_message.reply_photo(
            photo=banner,
            caption="👑 <b>BETROXY</b> — Play • Win • Enjoy",
            parse_mode=bot.ParseMode.HTML,
        )
    except Exception:
        bot.logger.exception("V54 themed welcome banner failed")
    return await _original_start(update, context)

bot.start = v54_start


def configure_open_app_menu():
    try:
        url = f"https://api.telegram.org/bot{bot.BOT_TOKEN}/setChatMenuButton"
        payload = {
            "menu_button": {
                "type": "web_app",
                "text": "Open App",
                "web_app": {"url": bot.APP_URL},
            }
        }
        r = requests.post(url, json=payload, timeout=15)
        r.raise_for_status()
        result = r.json()
        if not result.get("ok"):
            raise RuntimeError(str(result))
        bot.logger.warning("V54_OPEN_APP_MENU configured url=%s", bot.APP_URL)
    except Exception:
        bot.logger.exception("V54_OPEN_APP_MENU configuration failed")

configure_open_app_menu()
bot.logger.warning("V54_THEME_BANNER_OPEN_APP active=on")

if __name__ == "__main__":
    bot.main()
